package com.saxonica.ee.bytecode.iter;

import net.sf.saxon.expr.XPathContext;
import net.sf.saxon.om.FocusIterator;
import net.sf.saxon.om.Item;
import net.sf.saxon.om.SequenceIterator;
import net.sf.saxon.trans.UncheckedXPathException;
import net.sf.saxon.trans.XPathException;

/**
 * A CompiledFilterIterator filters an input sequence using a filter expression.
 */

public abstract class CompiledFilterIterator implements SequenceIterator {

    protected FocusIterator base;
    protected XPathContext filterContext = null;

    /**
     * Zero-argument constructor (used by generated bytecode)
     */

    public CompiledFilterIterator() {
    }

    /**
     * Set the base iterator and context
     *
     * @param base    the iterator over the sequence to be filtered
     * @param context the context in which the (outer) filter expression is evaluated
     */

    public final void setSequence(SequenceIterator base, XPathContext context) {
        filterContext = context.newMinorContext();
        filterContext.trackFocus(base);
        this.base = filterContext.getCurrentIterator();
    }

    /**
     * Get the next item if there is one
     */

    @Override
    public final Item next() {
        try {
            Item next;
            while ((next = base.next()) != null) {
                if (matches()) {
                    return next;
                }
            }
            return null;
        } catch (XPathException e) {
            throw new UncheckedXPathException(e);
        }
    }

    /**
     * Determine whether the context item matches the filter predicate
     *
     * @return true if the context item matches
     * @throws XPathException if an error occurs evaluating the predicate
     */

    protected abstract boolean matches() throws XPathException;

    @Override
    public void close() {
        base.close();
    }

    @Override
    public void discharge() {
        base.discharge();
    }


}

